#!/usr/bin/env bash
# Copies the generated JSON schemas from an evanalyzer checkout's docs/ into
# ./schemas so the extension ships a self-contained copy that works offline.
#
# The checkout defaults to the sibling ../evanalyzer; override it with
# EVANALYZER_DIR=/path/to/evanalyzer ./sync-schemas.sh
#
# The schemas in docs/ are generated by the cfg crate's build script
# (crates/cfg/build/json_schema_builder.rs) - run `cargo build -p cfg`
# (or a full workspace build) first if they might be stale.
set -euo pipefail
cd "$(dirname "$0")"

EVANALYZER_DIR="${EVANALYZER_DIR:-../evanalyzer}"
DOCS_DIR="${EVANALYZER_DIR}/docs"

for file in project.schema.json project_template.schema.json module_template.schema.json ai_learning.schema.json; do
  cp "${DOCS_DIR}/${file}" "schemas/${file}"
done

echo "Schemas synced from ${DOCS_DIR} into ./schemas"

# Regenerate the *.editor.schema.json variants used by jsonValidation. VS
# Code's built-in JSON language service doesn't merge $ref siblings (see
# scripts/build-editor-schemas.js for why), so these are kept alongside the
# raw schemas rather than pointing the editor straight at docs/ output.
node scripts/build-editor-schemas.js
